# Converting CameraImage to PNG in Flutter

Here are several approaches to convert a `CameraImage` (from the `camera` package) to a PNG image in Flutter.

## Method 1: Using the `image` Package (Recommended)

### Add dependencies
```yaml
dependencies:
  camera: ^0.10.5+9
  image: ^4.1.3
```

### For YUV420 Format (Android)
```dart
import 'package:camera/camera.dart';
import 'package:image/image.dart' as img;
import 'dart:typed_data';

Uint8List? convertCameraImageToPng(CameraImage cameraImage) {
  try {
    final img.Image image = _convertYUV420ToImage(cameraImage);
    final Uint8List png = Uint8List.fromList(img.encodePng(image));
    return png;
  } catch (e) {
    print("Error converting image: $e");
    return null;
  }
}

img.Image _convertYUV420ToImage(CameraImage cameraImage) {
  final int width = cameraImage.width;
  final int height = cameraImage.height;

  final int uvRowStride = cameraImage.planes[1].bytesPerRow;
  final int uvPixelStride = cameraImage.planes[1].bytesPerPixel!;

  final image = img.Image(width: width, height: height);

  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      final int uvIndex =
          uvPixelStride * (x / 2).floor() + uvRowStride * (y / 2).floor();
      final int index = y * width + x;

      final yValue = cameraImage.planes[0].bytes[index];
      final uValue = cameraImage.planes[1].bytes[uvIndex];
      final vValue = cameraImage.planes[2].bytes[uvIndex];

      // Convert YUV to RGB
      int r = (yValue + 1.370705 * (vValue - 128)).round().clamp(0, 255);
      int g = (yValue - 0.337633 * (uValue - 128) - 0.698001 * (vValue - 128))
          .round()
          .clamp(0, 255);
      int b = (yValue + 1.732446 * (uValue - 128)).round().clamp(0, 255);

      image.setPixelRgba(x, y, r, g, b, 255);
    }
  }

  return image;
}
```

### For BGRA8888 Format (iOS)
```dart
img.Image _convertBGRA8888ToImage(CameraImage cameraImage) {
  final int width = cameraImage.width;
  final int height = cameraImage.height;
  final Uint8List bytes = cameraImage.planes[0].bytes;

  final image = img.Image(width: width, height: height);

  for (int y = 0; y < height; y++) {
    for (int x = 0; x < width; x++) {
      final int index = (y * width + x) * 4;
      final int b = bytes[index];
      final int g = bytes[index + 1];
      final int r = bytes[index + 2];
      final int a = bytes[index + 3];

      image.setPixelRgba(x, y, r, g, b, a);
    }
  }

  return image;
}
```

### Platform-Aware Conversion
```dart
import 'dart:io';

Uint8List? convertCameraImageToPng(CameraImage cameraImage) {
  try {
    img.Image image;

    if (Platform.isAndroid) {
      image = _convertYUV420ToImage(cameraImage);
    } else if (Platform.isIOS) {
      image = _convertBGRA8888ToImage(cameraImage);
    } else {
      return null;
    }

    // Optional: fix rotation
    // image = img.copyRotate(image, angle: 90);

    return Uint8List.fromList(img.encodePng(image));
  } catch (e) {
    print("Error: $e");
    return null;
  }
}
```

## Method 2: Using `compute` for Performance (Isolate)

Since conversion is CPU-intensive, offload it to an isolate:

```dart
import 'package:flutter/foundation.dart';

// Data class to pass to isolate (CameraImage can't cross isolate boundaries directly)
class CameraImageData {
  final int width;
  final int height;
  final List<Uint8List> planes;
  final List<int> bytesPerRow;
  final List<int?> bytesPerPixel;
  final bool isAndroid;

  CameraImageData({
    required this.width,
    required this.height,
    required this.planes,
    required this.bytesPerRow,
    required this.bytesPerPixel,
    required this.isAndroid,
  });

  factory CameraImageData.fromCameraImage(CameraImage image) {
    return CameraImageData(
      width: image.width,
      height: image.height,
      planes: image.planes.map((p) => Uint8List.fromList(p.bytes)).toList(),
      bytesPerRow: image.planes.map((p) => p.bytesPerRow).toList(),
      bytesPerPixel: image.planes.map((p) => p.bytesPerPixel).toList(),
      isAndroid: Platform.isAndroid,
    );
  }
}

// Top-level function for isolate
Uint8List _convertInIsolate(CameraImageData data) {
  img.Image image;

  if (data.isAndroid) {
    image = _convertYUV420(data);
  } else {
    image = _convertBGRA8888(data);
  }

  return Uint8List.fromList(img.encodePng(image));
}

img.Image _convertYUV420(CameraImageData data) {
  final image = img.Image(width: data.width, height: data.height);
  final int uvRowStride = data.bytesPerRow[1];
  final int uvPixelStride = data.bytesPerPixel[1]!;

  for (int y = 0; y < data.height; y++) {
    for (int x = 0; x < data.width; x++) {
      final int uvIndex =
          uvPixelStride * (x / 2).floor() + uvRowStride * (y / 2).floor();
      final int index = y * data.width + x;

      final yVal = data.planes[0][index];
      final uVal = data.planes[1][uvIndex];
      final vVal = data.planes[2][uvIndex];

      int r = (yVal + 1.370705 * (vVal - 128)).round().clamp(0, 255);
      int g = (yVal - 0.337633 * (uVal - 128) - 0.698001 * (vVal - 128))
          .round()
          .clamp(0, 255);
      int b = (yVal + 1.732446 * (uVal - 128)).round().clamp(0, 255);

      image.setPixelRgba(x, y, r, g, b, 255);
    }
  }
  return image;
}

img.Image _convertBGRA8888(CameraImageData data) {
  final image = img.Image(width: data.width, height: data.height);
  final bytes = data.planes[0];

  for (int y = 0; y < data.height; y++) {
    for (int x = 0; x < data.width; x++) {
      final i = (y * data.width + x) * 4;
      image.setPixelRgba(x, y, bytes[i + 2], bytes[i + 1], bytes[i], bytes[i + 3]);
    }
  }
  return image;
}

// Usage
Future<Uint8List> convertAsync(CameraImage cameraImage) async {
  final data = CameraImageData.fromCameraImage(cameraImage);
  return await compute(_convertInIsolate, data);
}
```

## Usage in Camera Stream

```dart
late CameraController _controller;

void _startImageStream() {
  _controller.startImageStream((CameraImage image) async {
    // Throttle processing - skip frames if needed
    final Uint8List? pngBytes = await convertAsync(image);

    if (pngBytes != null) {
      // Save to file
      final file = File('${directory.path}/capture.png');
      await file.writeAsBytes(pngBytes);

      // Or display it
      // setState(() { _imageWidget = Image.memory(pngBytes); });
    }
  });
}
```

## Key Notes

| Aspect | Detail |
|--------|--------|
| **Android format** | YUV420 (NV21/YV12) — requires manual conversion |
| **iOS format** | BGRA8888 — simpler, single plane |
| **Performance** | Use `compute()` / isolates to avoid jank |
| **Rotation** | Camera images may need rotation (`img.copyRotate(image, angle: 90)`) |
| **Alternative** | For JPEG (faster/smaller), use `img.encodeJpg(image, quality: 85)` |
| **image package v4** | Uses `setPixelRgba()` instead of `setPixel()` with `getColor()` |

